#!/usr/bin/env bash
# A week of daily runs (2026-10-01..07); partners must be able to download
# every day's settlement.
. "$(dirname "$0")/lib.sh"
t_setup

for d in 20261001 20261002 20261003 20261004 20261005 20261006 20261007; do
  payout run "$d" 2>>"$T_WORK/run.err"; rc=$?
  assert_rc "daily run $d completes" "$rc" 0
  assert_contains "run $d got transfer tickets" "$(payout manifest "$d")" " T0"
done

expect_day() {  # report date rows net
  local line
  line=$(printf '%s\n' "$1" | grep "^$2 ")
  assert_contains "partner can download $2 settlement ($3 rows)" "$line" "$2  $(printf '%4d' "$3")"
  assert_contains "partner total for $2" "$line" "$4"
}

r1=$(payout receipts P001 20261001 20261007)
# Test helpers. Each test file sources this, calls t_setup, then asserts.
T_HOME=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
T_FAIL=0
T_PASS=0

t_setup() {
  T_WORK=$(mktemp -d)
  trap 't_cleanup' EXIT
  export PAYOUT_WORK_DIR="$T_WORK/work"
  export PAYOUT_OUT_DIR="$T_WORK/out"
  export PAYOUT_TXN_FILE="$T_HOME/fixtures/txns-202610.tsv"
  export PAYOUT_PARTNERS_FILE="$T_HOME/conf/partners.conf"
  export XFERQ_HOME="$T_WORK/spool"
  mkdir -p "$XFERQ_HOME"
}

t_cleanup() { [ -n "${T_WORK:-}" ] && rm -rf "$T_WORK"; }

# Loads the libraries into the test shell (for unit tests).
t_source_libs() {
  export LC_ALL=C.UTF-8
  export PAYOUT_HOME="$T_HOME"
  . "$T_HOME/steps/_env.sh"
}

payout() { "$T_HOME/bin/payout" "$@"; }

ok()   { T_PASS=$((T_PASS + 1)); printf 'ok   - %s\n' "$1"; }
fail() { T_FAIL=$((T_FAIL + 1)); printf 'FAIL - %s\n' "$1"; [ -n "${2:-}" ] && printf '       %s\n' "$2"; return 0; }

assert_eq() {
  if [ "$2" = "$3" ]; then ok "$1"; else fail "$1" "expected [$3] got [$2]"; fi
}

assert_contains() {
  if printf '%s' "$2" | grep -qF -- "$3"; then ok "$1"; else fail "$1" "missing [$3]"; fi
}

assert_rc() {
  if [ "$2" -eq "$3" ]; then ok "$1"; else fail "$1" "expected exit $3 got $2"; fi

